int main(){arduboy_pxa_boot(1);auto b=game();printf("{\"game_wire_bytes\":%zu,",b.size());need(b[0]==1&&b[1]==10&&b[2]==0,"typed bootstrap");need(arduboy_pxa_state.constructors==1,"cold constructor exactly once");need(b[17]==1,"audio original one channel");for(auto x:arduboy_pxa_state.eeprom)need(x==255,"fresh FF EEPROM");advance(2300);b=game();need(b[2]==1,"original 80 frames logo transitions title");need(arduboy_pxa_state.fault==0&&arduboy_pxa_state.dropped_steps==0,"provider admits real elapsed without drop");tap(4);b=game();need(b[2]==2,"original B menu callback starts game");advance(1000);tap(64);tap(16);tap(32);tap(128);tap(8);b=game();need(b[2]==2,"original A opens in game menu");tap(4);advance(100);b=game();need(b[2]==2,"original B continues");for(unsigned i=0;i<16;i++){tap((i%2)?64:32);tap(4);}advance(1000);auto before=game();uint8_t ee[1024];memcpy(ee,arduboy_pxa_state.eeprom,1024);unsigned clock=arduboy_pxa_state.clock_ms;arduboy_pxa_new();b=game();need(b[2]==0&&b[38]==80,"NEW returns original logo counter80");need(arduboy_pxa_state.clock_ms==clock,"NEW preserves activity clock");need(!memcmp(ee,arduboy_pxa_state.eeprom,1024),"NEW preserves session EEPROM");advance(2300);tap(16);tap(16);tap(4);b=game();need(b[2]==2,"original puzzle callback");tap(4);advance(250);for(unsigned i=0;i<32;i++){tap((i%4==0)?128:(i%4==1)?64:(i%4==2)?16:32);tap(4);}need(arduboy_pxa_state.fault==0&&arduboy_pxa_state.dropped_steps==0,"complete ordinary puzzle path no fault");printf("\"passed\":true,\"checks\":%d,\"ordinary_input_only\":true,\"native_boots\":1,\"native_restores\":0}\n",checks);}
